<?php
namespace App\Http\Controllers\Platform;
use App\Http\Controllers\Controller;use App\Models\Landlord\SubscriptionVoucher;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Validation\Rule;use Illuminate\View\View;
class SubscriptionVoucherController extends Controller { public function index(): View{return view('platform.vouchers.index',['vouchers'=>SubscriptionVoucher::query()->latest()->get()]);} public function store(Request $r): RedirectResponse{$d=$r->validate(['code'=>['required','alpha_dash','max:80','unique:landlord.subscription_vouchers,code'],'name'=>['required','string','max:255'],'discount_type'=>['required',Rule::in(['percent','fixed'])],'discount_value'=>['required','integer','min:1','max:999999999999'],'max_redemptions'=>['nullable','integer','min:1'],'starts_at'=>['nullable','date'],'ends_at'=>['nullable','date','after:starts_at']]);if($d['discount_type']==='percent'&&$d['discount_value']>100)return back()->withErrors(['discount_value'=>'Percentage cannot exceed 100.']);SubscriptionVoucher::query()->create($d+['is_active'=>true]);return back()->with('status','Voucher created.');} public function status(Request $r,SubscriptionVoucher $voucher):RedirectResponse{$d=$r->validate(['is_active'=>['required','boolean']]);$voucher->update($d);return back()->with('status','Voucher status saved.');}}
